    arg_clusters = {}
    arguments: Iterator[Any] = filter(None, [node.args.args, node.args.kwonlyargs])
    for arg in itertools.chain.from_iterable(arguments):
        if arg.name in arg_clusters:
            self.add_message(
                "duplicate-argument-name",
                node=arg,
                args=(arg.name,),
                confidence=HIGH,
            )
        else:
