                isinstance(a, nodes.GeneratorExp) for a in arg.args
            ):
                return

            if arg in redundant_calls:
                fixed_node.args = (
                    fixed_node.args[:i] + arg.args + fixed_node.args[i + 1 :]
                )
                break

        redundant_calls = self.get_redundant_calls(fixed_node, inferred)

    for idx, arg in enumerate(fixed_node.args):
        if not isinstance(arg, nodes.Const):
            if self._is_splattable_expression(arg):
                splat_node = nodes.Starred(
                    ctx=Context.Load,
                    lineno=arg.lineno,
                    col_offset=0,
                    parent=nodes.NodeNG(
                        lineno=None,
                        col_offset=None,
                        end_lineno=None,
                        end_col_offset=None,
                        parent=None,
                    ),
                    end_lineno=0,
                    end_col_offset=0,
                )
                splat_node.value = arg
                fixed_node.args = [
                    *fixed_node.args[:idx],
                    splat_node,
                    *fixed_node.args[idx + 1 :],
                ]
    func_name = (
        node.func.attrname
        if isinstance(node.func, nodes.Attribute)
        else node.func.name
    )
    self.add_message(
        "nested-min-max",
        node=node,
        args=(func_name, fixed_node.as_string()),
        confidence=INFERENCE,
    )

